        "Also when there are demyelinating features, or the diagnosis is in doubt. [ADA Diabetes Care 2017]",
        "Also to confirm a treatable entrapment before surgery. [API 11e 2019]",
        "**Nerve conduction studies test only large myelinated fibres**. [API 11e 2019]",
        "They are therefore **normal in pure small-fibre neuropathy** - a normal study does not disprove it. [API 11e 2019]",
        "Confirm small-fibre neuropathy with **skin biopsy for intra-epidermal nerve fibre density** or quantitative sensory testing. [API 11e 2019]",
        "In suspected **Guillain-Barre syndrome**, cerebrospinal fluid shows **albuminocytological dissociation**. [API 11e 2019]",
        "That is a raised protein with **fewer than 10 cells**. [API 11e 2019]",
        "It may be absent in the first week - a normal early tap does not exclude the diagnosis. [API 11e 2019]",
        "The essential monitoring test is **serial forced vital capacity**, not oxygen saturation. [API 11e 2019]",
        "Saturation falls only after the patient is close to arrest. [API 11e 2019]",
