        "Glycaemic control slows neuropathy only modestly in type 2 diabetes. [ADA Diabetes Care 2017]",
        "Stop alcohol, replace B12, and correct hypothyroidism. [API 11e 2019]",
        "Withdraw the offending drug, and start **multidrug therapy for leprosy**. [WHO Leprosy 2018]",
