        "First-line drugs are **amitriptyline, duloxetine, pregabalin and gabapentin**. [NICE CG173 2020]",
        "Choose by comorbidity, not by any claimed superiority. [NICE CG173 2020]",
        "**Amitriptyline 10-25 mg at night, titrated to 50-75 mg**, is cheapest and helps sleep. [NICE CG173 2020]",
