        "Often follows a diarrhoeal or respiratory illness. [API 11e 2019]",
        "Back pain and distal paraesthesiae occur, but objective sensory loss is slight. [API 11e 2019]",
        "**Admit immediately - about a quarter need ventilation**. [API 11e 2019]",
        "Monitor with the **20/30/40 rule**. [API 11e 2019]",
        "Anticipate intubation when **forced vital capacity falls below 20 mL/kg**. [API 11e 2019]",
        "Or when **maximum inspiratory pressure is weaker than -30 cmH2O**. [API 11e 2019]",
