        "A diabetic foot ulcer with surrounding cellulitis, purulence or probe-to-bone needs same-day admission. [IWGDF 2023]",
        "So does crepitus or systemic sepsis. [IWGDF 2023]",
        "Take wound cultures and start intravenous antibiotics. [IWGDF 2023]",
        "Image for osteomyelitis, arrange surgical debridement and assess the vascular supply. [IWGDF 2023]",
