        "**Rifampicin 600 mg orally twice daily for 2 days**, or 10 mg/kg twice daily in children over 1 month and 5 mg/kg twice daily under 1 month. [IDSA 2004]",
        "Alternatives: **ciprofloxacin 500 mg orally as a single dose, or ceftriaxone 250 mg intramuscularly once** - 125 mg under 12 years, and the drug of choice in pregnancy. [IDSA 2004]",
