        "Recurrence risk is highest with **calcified lesions and persistent perilesional oedema**. [IDSA 2018]",
        "Prevention is public health - hand washing, safe drinking water, washing raw vegetables, sanitation and latrine use, and pork inspection. [WHO 2023]",
        "**Treat the household taeniasis carrier** with a single dose of praziquantel 5-10 mg/kg or niclosamide, because that person is the source. [WHO 2023]",
