        "**Herpes simplex encephalitis**: fever, headache, confusion, personality or behavioural change, dysphasia and seizures, with a temporal lobe focus on MRI and electroencephalography. [Harrison 21e]",
        "**Start intravenous acyclovir 10 mg/kg 8-hourly for 14-21 days empirically on suspicion**, before the polymerase chain reaction result returns. [Harrison 21e]",
