        "The **Bell phenomenon**, the eye rolling up and out on attempted closure, is a normal reflex made visible by the palsy, not a sign of disease. [Adams and Victor 12e]",
        "**A droop on command with a symmetrical spontaneous smile** means a cortical lesion - volitional movement uses the corticobulbar tract, emotional movement does not.",
