        "**Stop any offending drug and review in 4-8 weeks** before labelling anyone as having Parkinson's disease. [NICE NG71 2017]",
        "**Start treatment when motor symptoms interfere with function, work or quality of life** - not at the moment of diagnosis. [NICE NG71 2017]",
        "**Delaying levodopa neither protects neurones nor postpones motor complications** (LEAP 2019, PD MED 2014). [NICE NG71 2017]",
        "**Dyskinesia tracks disease duration and cumulative dose, not the date levodopa started** - so do not withhold it from a disabled patient. [NICE NG71 2017]",
        "**Levodopa with carbidopa is the most effective drug for motor symptoms and quality of life**. [NICE NG71 2017]",
        "The standard Indian tablet is **levodopa 100 mg with carbidopa 25 mg**. [API 11e 2019]",
        "**Start half a tablet three times a day, or one tablet twice daily**, and titrate weekly to the lowest effective dose. [NICE NG71 2017]",
        "Usual maintenance is **300-600 mg of levodopa a day in 3-4 divided doses**. [NICE NG71 2017]",
        "**Give levodopa 30-60 minutes before food**, an hour before or two hours after a protein meal - amino acids compete for its transporter. [NICE NG71 2017]",
        "**The widely sold 100/10 formulation supplies too little carbidopa** unless taken four or more times a day. [API 11e 2019]",
        "**At least 75 mg of carbidopa daily is needed** to block peripheral decarboxylation and prevent nausea and postural drop. [API 11e 2019]",
