        "**Speech and language therapy (LSVT-LOUD)** for hypophonia, with swallowing assessment as soon as coughing on liquids appears. [NICE NG71 2017]",
        "Occupational therapy and a **home falls assessment** - loose rugs removed, grab rails, a raised toilet seat, night lighting, no bifocals on stairs. [NICE NG71 2017]",
