    "**Bradykinesia is mandatory** - and bradykinesia means decrement, not just slowness. If repetitive finger tapping does not fade in amplitude or speed, look for another diagnosis.",
    "Parkinson's disease **begins asymmetrically and stays asymmetric**. Symmetry from the start is the single most useful bedside pointer away from it.",
    "Before diagnosing Parkinson's disease in an Indian outpatient, **ask what tablets have been taken for gas, acidity, giddiness or headache** - levosulpiride, metoclopramide, flunarizine and cinnarizine make drug-induced parkinsonism the commonest reversible cause seen in general practice.",
    "**Postural instability is late.** Falls in the first year mean progressive supranuclear palsy; autonomic failure in the first years means multiple system atrophy; dementia in the first year means Lewy body dementia.",
    "**Tremor is absent in about one in five patients** with Parkinson's disease - the akinetic-rigid form is missed for years and mislabelled as depression, arthritis or ageing.",
    "**Levodopa is given on time, every time.** A missed or delayed hospital dose is a reportable adverse event, and abrupt withdrawal can precipitate a life-threatening parkinsonism-hyperpyrexia syndrome.",
    "**Never prescribe metoclopramide, prochlorperazine, haloperidol or risperidone to a parkinsonian patient.** Use domperidone for nausea and quetiapine (or clozapine with counts) for psychosis.",
    "**Ask about gambling, online shopping, hypersexuality and binge eating at every visit on a dopamine agonist - and ask the spouse, not only the patient.** Patients conceal it, and families lose their savings before anyone asks.",
