        "Recurrent early falls, characteristically backwards, within the first year, together with a vertical supranuclear gaze palsy affecting downgaze, symmetrical axial rigidity, an erect rather than stooped posture, the staring 'surprised' facies and an absent levodopa response, is the Richardson phenotype of progressive supranuclear palsy; downward vertical supranuclear gaze palsy is in fact an absolute exclusion criterion for idiopathic Parkinson's disease in the MDS criteria. Inadequate dosing does not explain the gaze palsy or the early falls, and although 400 mg of levodopa daily is short of the 600 mg that counts as an adequate trial, the gaze palsy and the early backward falls settle it. Multiple system atrophy is led by autonomic failure, cerebellar signs, antecollis and stridor, not by a downgaze palsy. Normal pressure hydrocephalus gives a magnetic gait with urinary incontinence and dementia, with the arms and eyes spared. Dementia with Lewy bodies is defined by early fluctuating cognition and visual hallucinations, which are absent here.",
      difficulty: "moderate",
