        "**Neuroimaging is NOT required in typical childhood absence epilepsy** - normal development, normal examination, typical EEG, good response. [NICE NG217 2022]",
        "**An MRI here wastes money and often needs sedation** - the yield in typical absence epilepsy is effectively nil. [NICE NG217 2022]",
        "**MRI IS indicated for focal clinical or EEG features, or an abnormal or asymmetric background** - both suggest a structural lesion. [NICE NG217 2022]",
        "**MRI is indicated for slow spike-and-wave under 2.5 Hz, an abnormal examination, or developmental delay** - none belongs to CAE. [NICE NG217 2022]",
        "**MRI is indicated when onset is before 4 or after 10 years** - both fall outside the childhood absence epilepsy window. [NICE NG217 2022]",
