        "**Blood tests are not routine** - do calcium, magnesium, sodium and glucose only when the history points at them. [NICE NG217 2022]",
        "**Take a baseline blood count and liver function before valproate** - mandatory under 2 years, where fatal hepatotoxicity is real. [NICE NG217 2022]",
        "**Assess attention and learning formally if school performance has fallen** - ADHD co-occurs in up to a third of children with CAE. [ILAE 2017]",
        "**Ethosuximide is first line when there are absence seizures only** - it matched valproate for efficacy with less attentional dysfunction. [Glauser NEJM 2010]",
        "**Ethosuximide and valproate gave 45% seizure freedom at 16 weeks against 21% for lamotrigine** - lamotrigine is the weaker drug. [Glauser NEJM 2010]",
        "**Start ethosuximide 250 mg daily, roughly 10-15 mg/kg/day** - a low start avoids the nausea that makes families stop it. [Glauser NEJM 2010]",
        "**Increase every 5-7 days to 20-30 mg/kg/day in two divided doses, maximum 1500 mg/day** - divided dosing limits the gastric upset. [Glauser NEJM 2010]",
        "**Ethosuximide causes nausea, anorexia, abdominal pain, hiccups, drowsiness and headache** - these, not failure, are why it is abandoned. [Glauser NEJM 2010]",
        "**Rarely it causes blood dyscrasias, drug-induced lupus and Stevens-Johnson syndrome** - any rash or unexplained fever stops the drug. [Glauser NEJM 2010]",
        "**Ethosuximide does not protect against generalised tonic-clonic seizures** - so one tonic-clonic seizure ever makes valproate the drug. [Glauser NEJM 2010]",
        "**Sodium valproate 15-20 mg/kg/day, titrated to 20-40 mg/kg/day, up to 60, in two divided doses** - titrate to seizure freedom. [NICE NG217 2022]",
        "**Valproate is the one drug covering absence, tonic-clonic and myoclonic seizures together** - which is why mixed syndromes get it. [NICE NG217 2022]",
        "**Valproate causes weight gain, tremor, hair loss, thrombocytopenia, hyperammonaemia and PCOS** - a heavy load for a growing girl. [NICE NG217 2022]",
        "**Teratogenicity above all makes valproate a poor long-term choice in a girl** - the decision must be made before menarche, not at it. [MHRA 2018]",
        "**Ethosuximide supply in India is intermittent, so many Indian units start valproate** - a defensible choice that should be stated, not hidden. [API 11e 2019]",
        "**Lamotrigine is third line - weaker for absences but cognitively better tolerated** - the choice when attention is the main problem. [Glauser NEJM 2010]",
        "**Lamotrigine 0.3 mg/kg/day for 2 weeks, then 0.6 mg/kg/day for 2 weeks** - slow titration is what prevents the rash. [NICE NG217 2022]",
        "**Then increase every 1-2 weeks to 1-10 mg/kg/day** - faster steps risk Stevens-Johnson syndrome. [NICE NG217 2022]",
        "**Halve every lamotrigine step and every target when it is combined with valproate** - valproate doubles lamotrigine levels. [NICE NG217 2022]",
        "**For truly refractory absences combine ethosuximide with valproate** - the standard pairing before diet or referral. [Glauser NEJM 2010]",
        "**A ketogenic or modified Atkins diet is the next step, and the specific treatment if GLUT1 deficiency is found** - the defect is glucose transport. [ILAE 2017]",
        "**Never give carbamazepine, oxcarbazepine or phenytoin in absence epilepsy** - they aggravate absence and myoclonic seizures. [NICE NG217 2022]",
        "**Gabapentin, pregabalin, vigabatrin and tiagabine are equally forbidden** - they can precipitate absence status epilepticus. [NICE NG217 2022]",
