        "**In Indian practice a contrast-enhanced CT head is a reasonable and often superior first test** - calcified neurocysticercosis is a CT finding. [API 11e 2019]",
        "**Urgent same-day CT for a focal deficit or failure to return to normal consciousness** - a mass lesion or bleed must be excluded tonight. [NICE NG217 2022]",
        "**Urgent CT for head injury, suspected infection or malignancy, anticoagulation, or severe headache** - each needs treatment today. [NICE NG217 2022]",
        "**Recurrence after one unprovoked seizure is 40-50% at 2 years, most in the first 6-12 months** - which is why the first year is watched. [MESS 2005]",
        "**Start a drug when recurrence risk approaches or exceeds 60%** - that is the ILAE threshold at which one seizure already means epilepsy. [ILAE 2014]",
        "**An epileptiform EEG or a causative structural lesion on imaging pushes the risk past 60%** - so treat after the first seizure. [ILAE 2014]",
        "**A remote symptomatic cause - prior stroke, head injury or CNS infection - does the same** - as does a nocturnal seizure. [ILAE 2014]",
        "**Treat when a further seizure would be catastrophic for the person's job or safety** - or when the patient chooses it knowing the odds. [NICE NG217 2022]",
        "**Immediate treatment shortens time to remission but does not change long-term seizure freedom** - so an informed decision to wait is legitimate. [MESS 2005]",
        "**Focal seizures - lamotrigine or levetiracetam first line** - both are effective and neither induces liver enzymes. [NICE NG217 2022]",
