        "**Generalised tonic-clonic - sodium valproate 1000-2000 mg/day is the most effective drug** - but only where valproate is permissible. [NICE NG217 2022]",
        "**Levetiracetam 1000-3000 mg/day or lamotrigine 100-400 mg/day when valproate is unsuitable** - both are the safer choice in a woman. [NICE NG217 2022]",
        "**Myoclonic seizures and juvenile myoclonic epilepsy - valproate, or levetiracetam in a woman** - lamotrigine may worsen the myoclonus. [NICE NG217 2022]",
