        "**Start one drug low, titrate to freedom or intolerance, then switch to a second single drug** - monotherapy controls about 70%. [NICE NG217 2022]",
        "**Valproate carries a major malformation rate of about 10%, much higher above 1000 mg/day** - neural tube defects lead the list. [MHRA 2018]",
        "**Valproate causes neurodevelopmental impairment in 30-40% of exposed children** - a mean IQ loss of 7-10 points and a several-fold rise in autism. [MHRA 2018]",
