        "**Tramadol, theophylline and fluoroquinolones lower the seizure threshold** - take a drug history in every status epilepticus. [API 11e 2019]",
        "**Isoniazid overdose needs pyridoxine gram for gram** - no other drug will stop those seizures. [API 11e 2019]",
        "**A convulsion in a pregnant or recently delivered woman is eclampsia until proved otherwise** - the drug is magnesium sulphate. [FOGSI 2022]",
