  pearls: [
    "Learn the ILAE 2014 definition in three limbs - two unprovoked seizures more than 24 hours apart, or one unprovoked seizure with a 10-year recurrence risk of at least 60%, or a diagnosed epilepsy syndrome. It is the commonest single mark in the paper.",
    "The diagnosis of epilepsy is made from an eyewitness account, not from an EEG. A normal EEG never excludes epilepsy and an incidental epileptiform discharge never makes the diagnosis.",
    "In a child with staring spells, the absence of a post-ictal phase is the most discriminating point in the history - a focal impaired awareness seizure leaves the child confused and tired, a typical absence does not.",
    "Three minutes of hyperventilation - blowing a paper windmill in the consulting room - reproduces an absence in over 90% of untreated childhood absence epilepsy. It costs nothing, it clinches the diagnosis, and repeated at follow-up it measures control.",
    "Ethosuximide is first line for typical childhood absence epilepsy because it matches valproate for efficacy with less attentional dysfunction - but it does not protect against a generalised tonic-clonic seizure, so a single convulsion means switching to valproate.",
    "Carbamazepine, oxcarbazepine, phenytoin, gabapentin, pregabalin, vigabatrin and tiagabine aggravate absence and myoclonic seizures - misclassifying juvenile myoclonic epilepsy as focal epilepsy and prescribing carbamazepine is the classic disaster.",
    "Do not order an MRI in a normally developing child with typical absences, a normal examination and 3 Hz generalised spike-and-wave. Do order one for focal features, atypical age, an abnormal examination or drug resistance.",
    "In India a contrast-enhanced CT is often the more useful first scan in adult-onset focal seizures, because it shows the calcified neurocysticercosis that MRI can miss.",
    "Sodium valproate must not be used in a girl or woman who could become pregnant unless nothing else works and reliable contraception is in place - 10% major malformations and 30-40% neurodevelopmental impairment. Lamotrigine and levetiracetam are the pregnancy drugs, with folic acid 5 mg daily.",
    "In status epilepticus, give two doses of benzodiazepine and no more, then move to a second-line drug - levetiracetam, valproate and fosphenytoin are equally effective (ESETT). A third benzodiazepine stops the breathing, not the seizure.",
  ],
